import subprocess


def _get_eth_ip(eth_name):
    eth_ip = subprocess.Popen(
        [r"ip address show label {} | grep 'inet ' | head -n1 | sed -r 's:.*inet (.+?)/.*:\1:'".format(eth_name)],
        shell=True,
        stdout=subprocess.PIPE,
    ).communicate()[0]
    return eth_ip.strip()


def _get_hostname():
    vm_hostname = subprocess.Popen(["hostname"], shell=True, stdout=subprocess.PIPE).communicate()[0]
    return vm_hostname.strip()


